-- Run as the dedicated Oracle test user (for example, METATEST).
-- This fixture is intentionally isolated with the MV_TEST_ prefix.
whenever sqlerror exit sql.sqlcode

begin
  execute immediate 'drop view MV_TEST_ORDER_SUMMARY';
exception when others then
  if sqlcode != -942 then raise; end if;
end;
/

begin
  execute immediate 'drop table MV_TEST_ORDERS cascade constraints purge';
exception when others then
  if sqlcode != -942 then raise; end if;
end;
/

begin
  execute immediate 'drop table MV_TEST_CUSTOMERS cascade constraints purge';
exception when others then
  if sqlcode != -942 then raise; end if;
end;
/

create table MV_TEST_CUSTOMERS (
  CUSTOMER_ID number generated by default as identity primary key,
  CUSTOMER_NAME varchar2(120) not null,
  EMAIL varchar2(255),
  CREATED_AT timestamp with time zone default systimestamp not null
);

create table MV_TEST_ORDERS (
  ORDER_ID number generated by default as identity primary key,
  CUSTOMER_ID number not null,
  ORDER_DATE date not null,
  AMOUNT number(12,2) not null,
  STATUS varchar2(30) default 'NEW' not null,
  constraint MV_TEST_ORDERS_CUSTOMER_FK
    foreign key (CUSTOMER_ID) references MV_TEST_CUSTOMERS(CUSTOMER_ID)
);

create or replace view MV_TEST_ORDER_SUMMARY as
select c.CUSTOMER_ID,
       c.CUSTOMER_NAME,
       count(o.ORDER_ID) as ORDER_COUNT,
       nvl(sum(o.AMOUNT), 0) as TOTAL_AMOUNT
  from MV_TEST_CUSTOMERS c
  left join MV_TEST_ORDERS o on o.CUSTOMER_ID = c.CUSTOMER_ID
 group by c.CUSTOMER_ID, c.CUSTOMER_NAME;

create or replace procedure MV_TEST_REFRESH as
begin
  update MV_TEST_ORDERS
     set STATUS = 'READY'
   where STATUS = 'NEW';
  commit;
end;
/

insert into MV_TEST_CUSTOMERS (CUSTOMER_NAME, EMAIL)
values ('Meta Test Customer', 'metatest@example.invalid');

insert into MV_TEST_ORDERS (CUSTOMER_ID, ORDER_DATE, AMOUNT, STATUS)
select CUSTOMER_ID, sysdate, 1250.50, 'NEW'
  from MV_TEST_CUSTOMERS
 where EMAIL = 'metatest@example.invalid';

commit;
